layout(color) uniform half4 amzp_lightColor;
layout(color) uniform half4 amzp_shineColor;
uniform float2 amzp_lightDir;
uniform float amzp_lightDepth;
uniform float amzp_height;
uniform float amzp_smoothing;



        const float3 luminanceWeighting = float3(0.2126, 0.7152, 0.0722);

        float lighting(float3 p, float3 n) {
            float3 lightPos = float3(amzp_lightDir.x/2.0, -amzp_lightDir.y/2.0, amzp_lightDepth*2.0) / 1000.0;
            float3 l = normalize(lightPos-p);
            return dot(n,l);
        }

        float directionalLighting(float3 p, float3 n) {
            float3 lightPos = float3(amzp_lightDir.x/2.0, -amzp_lightDir.y/2.0, amzp_lightDepth*2.0) / 1000.0;
            float3 l = normalize(lightPos);
            return dot(n,l);
        }

        float4 applyShading(float4 amzp_texColor, float3 p, float3 n, float d ) {
            float4 result = float4(0.);
            float a = smoothstep(30.0,9.,d);
            a *= smoothstep(0.3,0.2,n.z);
            if( int(amzp_shadingType) == 0 ) {                
                result = amzp_texColor * a;
            } else if( int(amzp_shadingType) == 1 ) {         
                float l = lighting(p,n);
                float3 tc = amzp_texColor.rgb;
                float3 surface = tc * amzp_ambient + tc * amzp_lightColor.rgb * l * (1.-amzp_ambient);
                surface *= amzp_lightIntensity;
                float s = abs(pow(l,amzp_spec));
                surface = mix(surface*(1.-amzp_shine*0.1),amzp_shineColor.rgb,amzp_shine*s);
                result = float4(surface, amzp_texColor.a);
            } else if( int(amzp_shadingType) == 2 ) {         
                float l = directionalLighting(p,n);
                float3 tc = amzp_texColor.rgb;
                float3 surface = tc * amzp_ambient + tc * amzp_lightColor.rgb * l * (1.-amzp_ambient);
                surface *= amzp_lightIntensity;
                float s = abs(pow(l,amzp_spec));
                surface = mix(surface*(1.-amzp_shine*0.1),amzp_shineColor.rgb,amzp_shine*s);
                result = float4(surface, amzp_texColor.a);
            } else if( int(amzp_shadingType) == 3 ) {         
                result = float4( (n/2.)+0.5, 1. ) * a;
            } else if( int(amzp_shadingType) == 4 ) {         
                result = float4( (n/2.)+0.5, 1. ) * a;
            } else if( int(amzp_shadingType) == 5 ) {         
                result = float4( (n/2.)+0.5, 1. ) * a;
            }

            return result;
        }

        float2 mapTexture( float2 texCoord, float rate ) {
            float texRad = amzp_texAngle * 0.0174533;
            float texCos = cos(texRad);
            float texSin = sin(texRad);
            float2x2 texRot = float2x2( texCos, -texSin, texSin, texCos );

            float texTwirl = 0.0;


            float texTwirlRad = texTwirl * 0.0174533;
            float texTwirlCos = cos(texTwirlRad);
            float texTwirlSin = sin(texTwirlRad);
            float2x2 texTwirlRot = float2x2( texTwirlCos, -texTwirlSin, texTwirlSin, texTwirlCos );

            float2 texScaleVec = float2(amzp_texScale,amzp_texScale);
            texScaleVec *= float2(amzp_texStretch.x,amzp_texStretch.y);

            texCoord -= amzp_texOffset * float2(1.0,-1.0) / 1000.0;
            texCoord -= 0.5;
            texCoord.x *= rate;
            texCoord *= texRot;
            texCoord.x /= rate;
            texCoord /= texScaleVec;
            texCoord += 0.5;




            texCoord -= 0.5;
            texCoord = texCoord * (1.-5./screen.zw);

            texCoord *= texTwirlRot;
            texCoord += 0.5;
            return texCoord;
        }

        void amzRender() {

            float2 st = amzScreenNorm();
            float2 fragSize;
            float curHeight = 0.0;
            float left = 0.0;
            float right = 0.0;
            float top = 0.0;
            float bottom = 0.0;
            float2 gradient = float2(0,0);

            if(int(amzp_imgNo) == 0) {

                st = (float4(st.xy, 0, 1)*amzScreenToLayer()).xy;
                st = mapTexture(st, screen.zw.x / screen.zw.y);
                if( (amzp_mirror>0.5) ) {
                    st = abs(mod(st,2.0)-1.0);
                } else {
                    st = mod(st, 1.);
                }
                st = mod(st, 1.);
                st = (float4(st.xy, 0,1)*amzLayerToScreen()).xy;
                st -= (amzLayerCenter()/screen.zw);
                st *= amzp_texCrop;
                st += (amzLayerCenter()/screen.zw);

                fragSize = float2(1.)/getTexSize((screen.zw/1.0)) * amzp_smoothing;
                curHeight = length(amzTexture(0, st).xyz*luminanceWeighting);
                left = length(amzTexture(0, float2(st.x - fragSize.x, st.y) ).xyz*luminanceWeighting);
                right = length(amzTexture(0, float2(st.x + fragSize.x, st.y) ).xyz*luminanceWeighting);
                top = length(amzTexture(0, float2(st.x, st.y + fragSize.y) ).xyz*luminanceWeighting);
                bottom = length(amzTexture(0, float2(st.x, st.y - fragSize.y) ).xyz*luminanceWeighting);
            } else if(int(amzp_imgNo) == 1) {

                st = (float4(st.xy, 0, 1)*amzScreenToLayer()).xy;
                st = mapTexture(st, screen.zw.x / screen.zw.y);
                if( (amzp_mirror>0.5) ) {
                    st = abs(mod(st,2.0)-1.0);
                } else {
                    st = mod(st, 1.);
                }
                st = mod(st, 1.);
                st = (float4(st.xy, 0,1)*amzLayerToScreen()).xy;
                st -= (amzLayerCenter()/screen.zw);
                st *= amzp_texCrop;
                st += (amzLayerCenter()/screen.zw);

                fragSize = float2(1.)/(screen.zw/1.0) * amzp_smoothing;
                curHeight = length(amzTexture(1, st).xyz*luminanceWeighting);
                left = length(amzTexture(1, float2(st.x - fragSize.x, st.y) ).xyz*luminanceWeighting);
                right = length(amzTexture(1, float2(st.x + fragSize.x, st.y) ).xyz*luminanceWeighting);
                top = length(amzTexture(1, float2(st.x, st.y + fragSize.y) ).xyz*luminanceWeighting);
                bottom = length(amzTexture(1, float2(st.x, st.y - fragSize.y) ).xyz*luminanceWeighting);
            } else if(int(amzp_imgNo) == 2) {
                st = (float4(st.xy, 0, 1)*amzScreenToLayer()).xy;
                st.x *= (layer.x / float2(1024.0,1024.0).x);
                st.y *= (layer.y / float2(1024.0,1024.0).y);
                st = mapTexture(st, 1.0);
                if( (amzp_mirror>0.5) ) {
                    st = abs(mod(st,2.0)-1.0);
                } else {
                    st = mod(st, 1.);
                }
                fragSize = float2(1.)/float2(1024.0,1024.0) * amzp_smoothing;
                curHeight = amzTexture(3, st).g;
                left = amzTexture(3, float2(st.x - fragSize.x, st.y)).g;
                right = amzTexture(3, float2(st.x + fragSize.x, st.y)).g;
                top = amzTexture(3, float2(st.x, st.y + fragSize.y)).g;
                bottom = amzTexture(3, float2(st.x, st.y - fragSize.y)).g;
            } else if(int(amzp_imgNo) == 3) {
                st = (float4(st.xy, 0, 1)*amzScreenToLayer()).xy;
                st.x *= (layer.x / float2(1024.0,1024.0).x);
                st.y *= (layer.y / float2(1024.0,1024.0).y);
                st = mapTexture(st, 1.0);
                if( (amzp_mirror>0.5) ) {
                    st = abs(mod(st,2.0)-1.0);
                } else {
                    st = mod(st, 1.);
                }
                fragSize = float2(1.)/float2(1024.0,1024.0) * amzp_smoothing;
                curHeight = amzTexture(3, st).r;
                left = amzTexture(3, float2(st.x - fragSize.x, st.y) ).r;
                right = amzTexture(3, float2(st.x + fragSize.x, st.y) ).r;
                top = amzTexture(3, float2(st.x, st.y + fragSize.y) ).r;
                bottom = amzTexture(3, float2(st.x, st.y - fragSize.y) ).r;
            } else if(int(amzp_imgNo) == 4) {
                st = (float4(st.xy, 0, 1)*amzScreenToLayer()).xy;
                st.x *= (layer.x / float2(1024.0,1024.0).x);
                st.y *= (layer.y / float2(1024.0,1024.0).y);
                st = mapTexture(st, 1.0);
                if( (amzp_mirror>0.5) ) {
                    st = abs(mod(st,2.0)-1.0);
                } else {
                    st = mod(st, 1.);
                }
                fragSize = float2(1.)/float2(1024.0,1024.0) * amzp_smoothing;
                curHeight = amzTexture(2, st).b;
                left = amzTexture(2, float2(st.x - fragSize.x, st.y) ).b;
                right = amzTexture(2, float2(st.x + fragSize.x, st.y) ).b;
                top = amzTexture(2, float2(st.x, st.y + fragSize.y) ).b;
                bottom = amzTexture(2, float2(st.x, st.y - fragSize.y) ).b;
            } else if(int(amzp_imgNo) == 5) { 
                st = (float4(st.xy, 0, 1)*amzScreenToLayer()).xy;
                st.x *= (layer.x / float2(1024.0,1024.0).x);
                st.y *= (layer.y / float2(1024.0,1024.0).y);
                st = mapTexture(st, 1.0);
                if( (amzp_mirror>0.5) ) {
                    st = abs(mod(st,2.0)-1.0);
                } else {
                    st = mod(st, 1.);
                }
                fragSize = float2(1.)/float2(1024.0,1024.0) * amzp_smoothing;
                curHeight = amzTexture(2, st).g;
                left = amzTexture(2, float2(st.x - fragSize.x, st.y) ).g;
                right = amzTexture(2, float2(st.x + fragSize.x, st.y) ).g;
                top = amzTexture(2, float2(st.x, st.y + fragSize.y) ).g;
                bottom = amzTexture(2, float2(st.x, st.y - fragSize.y) ).g;
            } else if(int(amzp_imgNo) == 6) {
                st = (float4(st.xy, 0, 1)*amzScreenToLayer()).xy;
                st.x *= (layer.x / float2(1024.0,1024.0).x);
                st.y *= (layer.y / float2(1024.0,1024.0).y);
                st = mapTexture(st, 1.0);
                if( (amzp_mirror>0.5) ) {
                    st = abs(mod(st,2.0)-1.0);
                } else {
                    st = mod(st, 1.);
                }
                fragSize = float2(1.)/float2(1024.0,1024.0) * amzp_smoothing;
                curHeight = amzTexture(2, st).r;
                left = amzTexture(2, float2(st.x - fragSize.x, st.y) ).r;
                right = amzTexture(2, float2(st.x + fragSize.x, st.y) ).r;
                top = amzTexture(2, float2(st.x, st.y + fragSize.y) ).r;
                bottom = amzTexture(2, float2(st.x, st.y - fragSize.y) ).r;
            }
            else if(int(amzp_imgNo) == 7) { 
                st = (float4(st.xy, 0, 1)*amzScreenToLayer()).xy;
                st.x *= (layer.x / float2(1024.0,1024.0).x);
                st.y *= (layer.y / float2(1024.0,1024.0).y);
                st = mapTexture(st, 1.0);
                if( (amzp_mirror>0.5) ) {
                    st = abs(mod(st,2.0)-1.0);
                } else {
                    st = mod(st, 1.);
                }
                fragSize = float2(1.)/float2(1024.0,1024.0) * amzp_smoothing;
                curHeight = amzTexture(3, st).b;
                left = amzTexture(3, float2(st.x - fragSize.x, st.y) ).b;
                right = amzTexture(3, float2(st.x + fragSize.x, st.y) ).b;
                top = amzTexture(3, float2(st.x, st.y + fragSize.y) ).b;
                bottom = amzTexture(3, float2(st.x, st.y - fragSize.y) ).b;
            }
            gradient = normalize(float2((right - left) / (2.*fragSize.x), (top - bottom) / (2.*fragSize.y)));

            float adjHeight = amzp_height / 10.0;
            curHeight *= adjHeight;
            left *= adjHeight;
            right *= adjHeight;
            top *= adjHeight;
            bottom *= adjHeight;

            float3 va = normalize(float3(fragSize.x*2.0,0.0,right-left));
            float3 vb = normalize(float3(0.0,fragSize.y*2.0,top-bottom));
            float3 n = normalize(cross(va,vb));

            float4 baseColor;
            if(int(amzp_texNo) == 0) {
                baseColor = amzTexture(1, amzScreenNorm());
            } else if(int(amzp_texNo) == 1) {
                baseColor = amzTexture(0, amzScreenNorm());
            } else {
                baseColor = amzp_texColor;
            }

            baseColor = applyShading(baseColor,float3(amzScreenNorm().x - 0.5, amzScreenNorm().y - 0.5, curHeight), n, 1.0);
            float alpha = amzTexture(0, amzScreenNorm()).a;
            float4 result = baseColor*alpha;
            if(false)
            {
                float2 ld = amzScreenNorm() - ((amzLayerCenter()/screen.zw)+float2(amzp_lightDir.x/2.0, -amzp_lightDir.y/2.0)/1000.0);
                ld.x *= screen.zw.x / screen.zw.y;
                float4 amzp_lightColor= float4(0.);
                float lightSize = 0.02;
                float amzp_lightIntensity = 0.5;
                result = mix(result,amzp_lightColor,amzp_lightIntensity * smoothstep(0., .05, max(0.,lightSize-length(ld))*(1.0/lightSize)));
                amzp_lightColor= float4(1.,1.,1.,1.);
                lightSize = 0.01;
                amzp_lightIntensity = 1.0;
                result = mix(result,amzp_lightColor,amzp_lightIntensity * smoothstep(0., .05, max(0.,lightSize-length(ld))*(1.0/lightSize)));
            }
            amzOutput = result;

        }


half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
